// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(uint256 amount, uint256 fundAmount) public {
        vm.assume(amount > 0);
        vm.assume(fundAmount > 0 && fundAmount <= 1 ether);
        address attacker = address(new Attacker());
        vm.deal(attacker, 0.1 ether);
        vm.deal(address(c), fundAmount);
        uint256 attackerBefore = attacker.balance;
        vm.prank(attacker);
        try c.Command{value: amount}(address(attacker), abi.encodeWithSignature("drain()")) { } catch { }
        assertTrue(attacker.balance == attackerBefore);
    }
}

contract Attacker {
    function drain() external payable {
        selfdestruct(payable(msg.sender));
    }
}
